y, from andamen_db.maplemonk.andamen_db_sales_consolidated a left join sku_grn_first_date b on upper(a.sku) = upper(b.sku) where a.order_date::date >= b.first_grn_date::date and b.first_grn_date::date is not null and order_status not in (\'CANCELLED\',\'SHIPPED - RETURNED TO SELLER\',\'SHIPPED - LOST IN TRANSIT\',\'RETURNED\',\'SHIPPED - RETURNING TO SELLER\') and shipping_status not in (\'RTO DELIVERED\',\'RTO IN TRANSIT\',\'CANCELED\',\'LOST\',\'SHIPMENT LOST\',\'DELIVERED TO ORIGIN\',\'RETURNED\',\'RTO INITIATED\',\'RTO NDR\',\'DISPOSED OFF\') group by 1,2,3 ) ), fifo_allocation AS ( select * from ( select a.* , b.running_sales_quantity , b.order_timestamp , b.order_id , row_number() over (partition by po_id, a.sku, a.units_bought, first_grn_date, running_grn_quantity order by b.order_timestamp asc) rw from grn_running_total a left join gross_sales_running_total b on lower(a.sku) = lower(b.sku) and b.order_timestamp::date >= a.first_grn_date::date and a.running_grn_quantity <= b.running_sales_quantity ) where rw = 1 ) select po_id, sku, units_bought, running_grn_quantity, running_sales_quantity, case when (running_grn_quantity - running_sales_quantity) < 0 then units_bought when (running_grn_quantity - running_sales_quantity) >= 0 and (running_grn_quantity - running_sales_quantity) >= units_bought then 0 else (running_sales_quantity - ifnull(lag(running_grn_quantity) over (partition by sku order by po_id asc),0)) end allocated_quantity from ( SELECT fa.po_id, fa.sku, fa.units_bought, fa.running_grn_quantity, max(coalesce(fa.running_sales_quantity,sr.running_sales_quantity,0)) AS running_sales_quantity FROM fifo_allocation fa left join (select sku , order_id , order_timestamp , ifnull(running_sales_quantity,0) running_sales_quantity from gross_sales_running_total qualify row_number() over (partition by sku, order_id order by ifnull(running_sales_quantity,0) desc) =1 ) sr on upper(fa.sku) = upper(sr.sku) GROUP BY 1,2,3,4 ORDER BY fa.sku, fa.po_id ); create or replace table andamen_db.maplemonk.andamen_db_exit_margin_report as select a.po_id, a.sku, first_grn_Date, units_bought, price cogp, mrp, div0(mrp, price) buying_multiple, 0.15 as assumed_discount, div0(price, (mrp*(1-0.05)/1.12)) assumed_cogs, units_bought*mrp gross_mrp_value, units_bought*price total_cogp, grosssales.discount_percent actual_discount, div0(mrp*(1-grosssales.discount_percent),1.12) arv, pan.net_quantity nrv_Sale_units, div0(mrp*(1-grosssales.discount_percent),1.12) * pan.net_quantity nrv_Sale_value, div0(price,div0(mrp*(1-grosssales.discount_percent),1.12)) actual_cogs_percent, div0(pan.net_quantity, units_bought) st, pag.gross_quantity gob_units, div0(pag.gross_quantity - pan.net_quantity,pag.gross_quantity) leakages_percent, pag.gross_quantity - pan.net_quantity leakage_units, (pag.gross_quantity - pan.net_quantity)*500 leakages_cost, div0(mrp*(1-grosssales.discount_percent),1.12) * pan.net_quantity - units_bought*price - (pag.gross_quantity - pan.net_quantity)*500 exit_margin, div0(div0(mrp*(1-grosssales.discount_percent),1.12) * pan.net_quantity - units_bought*price - (pag.gross_quantity - pan.net_quantity)*500 , units_bought*mrp) exit_margin_percent, div0(units_bought*price + (pag.gross_quantity - pan.net_quantity)*500, div0(mrp*(1-grosssales.discount_percent),1.12)) units_to_breakeven, pm.live_Date from (select po_id, upper(A.value:sku::string) sku, min(grn_created_at::date) first_grn_Date, sum(ifnull(A.value:original_quantity::float,0)) units_bought, div0(sum(A.value:grn_detail_price::float),sum(ifnull(A.value:original_quantity::float,0))) price from (select * from andamen_db.maplemonk.andamen_ee_location_1_grn_details union all select * from andamen_db.maplemonk.andamen_ee_location_2_grn_details union all select * from andamen_db.maplemonk.andamen_ee_location_3_grn_details), lateral flatten(input => grn_items) A group by 1,2 ) a left join (select upper(sku) SKU , mrp , live_Date from ( select sku, mrp, created_at::Date live_Date, row_number() over (partition by upper(sku) order by 1) rw from andamen_db.maplemonk.easyecom_easyecom_andamen_product_master ) where rw = 1 ) pm on upper(a.sku) = upper(pm.sku) left join ( select upper(sku) SKU , sum(quantity) net_quantity from andamen_db.maplemonk.andamen_db_sales_consolidated where order_status not in (\'CANCELLED\',\'SHIPPED - RETURNED TO SELLER\',\'SHIPPED - LOST IN TRANSIT\',\'RETURNED\',\'SHIPPED - RETURNING TO SELLER\') and shipping_status not in (\'RTO DELIVERED\',\'RTO IN TRANSIT\',\'CANCELED\',\'LOST\',\'SHIPMENT LOST\',\'DELIVERED TO ORIGIN\',\'RETURNED\',\'RTO INITIATED\',\'RTO NDR\' ,\'DISPOSED OFF\') group by 1 ) netsales on upper(a.sku) = upper(netsales.sku) left join ( select upper(sku) SKU ,div0(sum(discount) , sum(ifnull(selling_price,0) + ifnull(discount,0))) discount_percent from andamen_db.maplemonk.andamen_db_sales_consolidated group by 1 ) grosssales on upper(a.sku) = upper(grosssales.sku) left join ( select po_id , upper(sku) SKU , allocated_quantity gross_quantity from andamen_db.maplemonk.po_allocation_gross_sales ) pag on upper(pag.sku) = upper(a.sku) and pag.po_id = a.po_id left join ( select po_id , sku , allocated_quantity net_quantity from andamen_db.maplemonk.po_allocation_net_sales ) pan on upper(pan.sku) = upper(a.sku) and pan.po_id = a.po_id ;",
